###############################################################
# PREVALENCE AND RF SUMMARIES FOR BINARY OUTCOME SIMULATIONS
###############################################################
# PURPOSE
# Summarize outcome prevalence and random-forest out-of-bag classification
# error for datasets generated by the binary logistic model.
#
# WHY THIS MATTERS
# These summaries describe the generated class proportions and RF prediction
# performance across the selected simulation settings.
#
# WHEN TO RUN
# This check is independent of all other pilots.
###############################################################
library("glmnet")
library("xtable")
library("ranger")

# PURPOSE
# Generate dataset from DGM.
#
# WHY THIS FUNCTION EXISTS
# Generates the data for analysis similarly to the main simulation but with a 
# binary target variable.
#
# INPUTS
# k: number of active variables per block
# rho: pairwise correlation within each b x b block
# n: number of training samples (default: 200)
# p: dimension of the matrix (default: 1000)
# SNR: coefficient-scaling parameter (default: 2)
# a: proportion of active blocks (default: 0.25)
# b: block size (default: 10)
#
# RETURN VALUE
# A data.frame with n rows. The first p columns X.1,...,X.p are the covariables  
# and the last column y is the binary outcome variable.
genData <- function(k, rho, n = 200, p = 1000, SNR = 2, a = 0.25, b = 10) {
  # Use block-diagonal structure and pre-compute Cholesky decomposition of single
  # block
  S <- matrix(rho, b, b) + (1 - rho) * diag(b)
  L <- chol(S)   
  m <- floor(p / b)
  # Draw independent normal observations per block
  Z <- matrix(rnorm(n * b * m), n * m, b)
  # Multiply with Cholesky matrix L = Sigma^(1/2)
  Y <- Z %*% L
  # Rearrange such that blocks of variables are in columns
  X <- matrix(
    aperm(array(Y, dim = c(n, m, b)), c(1, 3, 2)),
    nrow = n
  )
  
  # Draw coefficients from U(0.5, 1.5) for indices selected by p*a and
  # the modulo condition. Set all other coefficients to zero.
  beta <- ifelse((1:p <= p * a) & ((1:p %% 10) <= k), runif(p, 0.5, 1.5), 0)
  
  # Calculate coefficient normalization V0
  V0 <- sum(beta^2) +
    rho * sum(sapply(1:m, function(g) {sum(beta[(b*(g-1)+1):(b*g)])^2}))
  
  # Multiply coefficients by sqrt(SNR / V0)
  beta <- c(0, sqrt(SNR / V0) * beta)
  
  # Draw binary outcome following logistic regression model
  y <- rbinom(n, 1, prob = 1 / (1 + exp(-cbind(1, X) %*% beta)))
  
  return(data.frame(X = X, y = y))
}

###############################################################
# Draw 1000 datasets from all settings for simulation with binary outcome, i.e.
# - all combinations of k = 1, 5, 10 and rho = 0, 0.6, 0.8, 0.95,
# - n = 200,
# - p/n = 5,
# - a = 0.25,
# - SNR = 2.
# For each dataset, calculate proportion of ones in outcome y.
set.seed(2026)
res <- mapply(function(k, rho) {replicate(1000, mean(genData(k, rho)$y == 1))}, 
              k = rep(c(1, 5, 10), 4), rho = rep(c(0, 0.6, 0.8, 0.95), each = 3), 
              SIMPLIFY = FALSE)
# Print (LaTeX) table of summary()s for each combination of rho and k of 
# resulting prevalences across the 1000 generated datasets
tab <- t(sapply(res, summary))
tab <- cbind(rep(c(1, 5, 10), 4), rep(c(0, 0.6, 0.8, 0.95), each = 3), tab)
colnames(tab)[1:2] <- c("$k$", "$\\rho$")
rownames(tab) <- NULL
print.xtable(xtable(tab, label = "tab:prev.bin", 
                    digits = c(0, 0, 1, rep(2, 6)), 
                    caption = paste0("Summaries of prevalences of binary outcome ", 
                                     "in 1000 simulated datasets.")), 
             include.rownames = FALSE,
             sanitize.colnames.function = function(x) x,
             caption.placement = "top", 
             booktabs = TRUE)


# Draw 100 datasets from all settings for simulation with binary outcome.
# For each dataset, calculate the out-of-bag prediction error of a random forest
# for predicting the binary outcome.
set.seed(2026)
res.pred <- mapply(function(k, rho) replicate(100, {
    ranger(y~., data = genData(k, rho, SNR = 2, a = 0.25), 
           classification = TRUE)$prediction.error
  }),
  k = rep(c(1, 5, 10), 4), 
  rho = rep(c(0, 0.6, 0.8, 0.95), each = 3), 
  SIMPLIFY = FALSE)
# Print (LaTeX) table of summary()s for each combination of rho and k of 
# resulting performances across the 100 generated datasets
tab <- t(sapply(res.pred, summary))
tab <- cbind(rep(c(1, 5, 10), 4), rep(c(0, 0.6, 0.8, 0.95), each = 3), tab)
colnames(tab)[1:2] <- c("$k$", "$\\rho$")
rownames(tab) <- NULL
print.xtable(xtable(tab, label = "tab:pred.bin", 
                    digits = c(0, 0, 2, rep(2, 6)), 
                    caption = paste0("Summaries of OOB prediction errors for ", 
                                     "random forest on 100 simulated datasets.")), 
             include.rownames = FALSE,
             sanitize.colnames.function = function(x) x,
             caption.placement = "top", 
             booktabs = TRUE)

